async function resolveTenant(request, env) {
  const url = new URL(request.url);
  const hostname = url.hostname.toLowerCase();
  let subdomain = null;
  const schoolParam = url.searchParams.get("school") || url.searchParams.get("tenant");
  if (schoolParam) {
    subdomain = schoolParam.trim().toLowerCase();
  } else {
    const mainDomain = (env.MAIN_DOMAIN || "").toLowerCase().trim();
    if (mainDomain && hostname.endsWith("." + mainDomain)) {
      const prefix = hostname.replace("." + mainDomain, "");
      if (prefix && prefix !== "www" && !prefix.includes(".")) {
        subdomain = prefix;
      }
    } else {
      const parts = hostname.split(".");
      if (parts.length >= 3 && parts[0] !== "www") {
        subdomain = parts[0];
      }
    }
  }
  if (!subdomain) {
    return {
      ok: false,
      status: 400,
      error: "Tafadhali tumia Subdomain ya shule yako (mfano: https://shule.domainyako.com) au weka parameter ya '?school=slug' kwenye URL."
    };
  }
  try {
    const stmt = env.DB.prepare(
      `SELECT id, name, subdomain, education_level, plan, status, max_students, 
              logo_url, contact_email, contact_phone, subscription_expires_at 
       FROM schools WHERE lower(trim(subdomain)) = ? LIMIT 1`
    );
    const school2 = await stmt.bind(subdomain.toLowerCase()).first();
    if (!school2) {
      return {
        ok: false,
        status: 404,
        error: `Shule yenye anwani ya '${subdomain}' haijajajajiliwa au haipatikani kwenye mfumo.`
      };
    }
    if (school2.status === "suspended") {
      return {
        ok: false,
        status: 403,
        error: `Akaunti ya shule ya '${school2.name}' imesimamishwa (Suspended). Tafadhali wasiliana na Msimamizi wa Mfumo.`
      };
    }
    if (school2.subscription_expires_at) {
      const expiryDate = new Date(school2.subscription_expires_at).getTime();
      const currentDate = Date.now();
      if (!isNaN(expiryDate) && expiryDate < currentDate) {
        return {
          ok: false,
          status: 402,
          error: `Muda wa matumizi wa kifurushi cha shule ya '${school2.name}' umeisha tarehe ${school2.subscription_expires_at}. Tafadhali fanya malipo ili kuendelea kutumia mfumo.`
        };
      }
    }
    return {
      ok: true,
      tenant: {
        id: school2.id,
        name: school2.name,
        subdomain: school2.subdomain,
        educationLevel: school2.education_level || "O-Level",
        plan: (school2.plan || "basic").toLowerCase(),
        status: school2.status || "active",
        maxStudents: school2.max_students || 500,
        logoUrl: school2.logo_url || "",
        contactEmail: school2.contact_email || "",
        contactPhone: school2.contact_phone || "",
        subscriptionExpiresAt: school2.subscription_expires_at
      }
    };
  } catch (error) {
    return {
      ok: false,
      status: 500,
      error: `Hitilafu ya Server wakati wa kutafuta shule: ${error.message}`
    };
  }
}
