    function getSubjectMappingSummary2(subjectName) {
      try {
        var ss = SpreadsheetApp.getActiveSpreadsheet();
        var filterSub = (subjectName || "").toString().trim().replace(/\s+/g, "").replace(/[^a-zA-Z0-9]/g, "").toLowerCase();
        var CLASS_DISPLAY = ["Form 1", "Form 2", "Form 3", "Form 4"];
        var SUBJECT_DISPLAY = ["Chemistry", "Biology", "History", "Computer Science"];
        var results = [];
        ss.getSheets().forEach(function(sh) {
          var name = sh.getName();
          if (name.indexOf("Map_") !== 0)
            return;
          var rest = name.substring(4);
          var uscore = rest.indexOf("_");
          if (uscore < 0)
            return;
          var classPart = rest.substring(0, uscore);
          var subjectPart = rest.substring(uscore + 1);
          if (filterSub && subjectPart.toLowerCase().indexOf(filterSub) < 0)
            return;
          var count = Math.max(0, sh.getLastRow() - 1);
          var displayClass = classPart;
          var displaySubject = subjectPart;
          CLASS_DISPLAY.forEach(function(c) {
            if (c.replace(/\s+/g, "").toLowerCase() === classPart.toLowerCase())
              displayClass = c;
          });
          SUBJECT_DISPLAY.forEach(function(s) {
            if (s.replace(/\s+/g, "").replace(/[^a-zA-Z0-9]/g, "").toLowerCase() === subjectPart.toLowerCase())
              displaySubject = s;
          });
          results.push({ subjectName: displaySubject, className: displayClass, count });
        });
        results.sort(function(a, b) {
          return a.subjectName.localeCompare(b.subjectName) || a.className.localeCompare(b.className);
        });
        return results;
      } catch (e) {
        return [];
      }
    }
